+        _ => None,
+    };
+
+    if let Some(id) = alias_id {
+        if let Some(spec) = modes.iter().find(|spec| spec.id == id) {
+            return Ok(spec);
+        }
+    }
+
+    Err(format!("Unsupported launch mode: {mode_id}"))
