+      apiKeys={keys}
+      appVersionInfo={null}
+      balanceLoading={false}
+      channels={[defaultChannel()]}
+      currentChannel={defaultChannel()}
+      darkMode={false}
+      keySelections={{ claude: 1, codex: 2, gemini: 3, opencode: 2 }}
